package mrpapermoon.whisper.mesh.dbimport android.content.Contextimport androidx.room.Databaseimport androidx.room.Roomimport androidx.room.RoomDatabaseimport androidx.room.TypeConvertersimport mrpapermoon.whisper.mesh.transformation.RoomTypeConverters@Database(	entities = [		NetworkMessageEntity::class,		WhispererEntity::class,	],	version = 1,	exportSchema = false)@TypeConverters(RoomTypeConverters::class)abstract class RumorDatabase : RoomDatabase() {	abstract fun networkMessageDao(): NetworkMessageDao	abstract fun whispererDao(): WhispererDao	companion object {		@Volatile		private var INSTANCE: RumorDatabase? = null		fun getDatabase(context: Context): RumorDatabase {			return INSTANCE ?: synchronized(this) {				val instance = Room.databaseBuilder(					context.applicationContext,					RumorDatabase::class.java,					"whisper_mesh_database"				).build()				INSTANCE = instance				instance			}		}	}}